const $=id=>document.getElementById(id);let mode="mixed",count=10,round=[],index=0,score=0,streak=0,best=0,correct=0,time=18,timer,locked=false;
$("companyCount").textContent=companies.length;$("record").textContent=localStorage.getItem("gb-record-v2")||0;
document.querySelectorAll(".mode").forEach(b=>b.onclick=()=>{document.querySelectorAll(".mode").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");mode=b.dataset.mode});
document.querySelectorAll("[data-count]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-count]").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");count=+b.dataset.count});
const shuffle=a=>[...a].sort(()=>Math.random()-.5),show=id=>{document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));$(id).classList.add("active")};
function distractors(c){let pool=shuffle(companies.filter(x=>x.name!==c.name&&x.group===c.group));if(pool.length<3)pool=[...pool,...shuffle(companies.filter(x=>x.name!==c.name&&x.group!==c.group))];return pool.slice(0,3)}
function start(){round=shuffle(companies).slice(0,Math.min(count,companies.length)).map((company,i)=>({company,type:mode==="mixed"?["logo","category","clue"][i%3]:mode}));index=score=streak=best=correct=0;show("game");render()}
function render(){clearInterval(timer);locked=false;time=18;$("timer").textContent=time;$("streak").textContent="🔥 "+streak;$("score").textContent=score;$("scoreTop").textContent=score+" poeng";$("questionNumber").textContent=`Spørsmål ${index+1} av ${round.length}`;$("progressBar").style.width=`${index/round.length*100}%`;$("feedback").textContent="";$("feedback").className="feedback";$("next").classList.add("hidden");const q=round[index],c=q.company,v=$("visual");v.innerHTML="";
if(q.type==="category"){v.innerHTML=`<span class="monogram">${c.mark}</span>`;$("questionType").textContent="TJENESTEKUNNSKAP";$("question").textContent=`Hva er ${c.name} spesielt knyttet til?`;$("subquestion").textContent="Velg den mest presise tjenesten.";renderServiceAnswers(c)}
else{if(q.type==="logo"){v.innerHTML=`<div class="brand-tile group-${c.group}"><b>${c.mark}</b><small>${c.domain.split(".")[0].replaceAll("-"," ")}</small></div>`;$("questionType").textContent="GJETT MERKEUTSNITTET";$("question").textContent="Hvilken bedrift tilhører dette merkeuttrykket?";$("subquestion").textContent="Svaralternativene er hentet fra samme bransje."}else{v.innerHTML="<span class='monogram'>?</span>";$("questionType").textContent="DETALJSPØRSMÅL";$("question").textContent="Hvilken bedrift passer til denne opplysningen?";$("subquestion").textContent=c.clue}renderCompanyAnswers(c)}
timer=setInterval(()=>{time--;$("timer").textContent=time;if(time<=0){clearInterval(timer);answer(null,false,c.name)}},1000)}
function renderCompanyAnswers(c){const box=$("answers");box.innerHTML="";shuffle([c,...distractors(c)]).forEach((choice,i)=>addAnswer(box,`${String.fromCharCode(65+i)}  ${choice.name}`,choice.name===c.name,c.name))}
function renderServiceAnswers(c){const box=$("answers");box.innerHTML="";const services=shuffle([c.service,...shuffle(companies.filter(x=>x.name!==c.name&&x.group===c.group).map(x=>x.service)).slice(0,3)]);while(services.length<4)services.push(shuffle(companies.filter(x=>!services.includes(x.service))).pop().service);services.forEach((text,i)=>addAnswer(box,`${String.fromCharCode(65+i)}  ${text}`,text===c.service,c.service))}
function addAnswer(box,text,isCorrect,correctValue){const b=document.createElement("button");b.className="answer";b.textContent=text;b.onclick=()=>answer(b,isCorrect,correctValue);b.dataset.correct=isCorrect?"1":"0";box.appendChild(b)}
function answer(button,isCorrect,correctValue){if(locked)return;locked=true;clearInterval(timer);document.querySelectorAll(".answer").forEach(b=>{b.disabled=true;if(b.dataset.correct==="1")b.classList.add("correct")});if(isCorrect){const gained=120+time*6+streak*15;score+=gained;streak++;correct++;best=Math.max(best,streak);$("feedback").textContent=`Riktig! +${gained} poeng`;$("feedback").classList.add("good")}else{streak=0;if(button)button.classList.add("wrong");$("feedback").textContent=`Riktig svar: ${correctValue}`;$("feedback").classList.add("bad")}$("score").textContent=score;$("streak").textContent="🔥 "+streak;$("next").classList.remove("hidden")}
function next(){index++;index>=round.length?finish():render()}
function finish(){const accuracy=Math.round(correct/round.length*100),old=+(localStorage.getItem("gb-record-v2")||0);if(score>old)localStorage.setItem("gb-record-v2",score);$("record").textContent=Math.max(old,score);$("finalScore").textContent=score;$("correctCount").textContent=`${correct}/${round.length}`;$("bestStreak").textContent=best;$("accuracy").textContent=accuracy+"%";$("resultEmoji").textContent=accuracy>=80?"🏆":accuracy>=50?"👏":"🧠";$("resultTitle").textContent=accuracy>=80?"Bedriftsekspert!":accuracy>=50?"Godt jobbet!":"Denne var vanskelig";$("resultText").textContent=accuracy>=80?"Du kan detaljene om kundene.":"Prøv igjen og slå rekorden din.";show("result")}
$("play").onclick=start;$("next").onclick=next;$("again").onclick=()=>show("start");$("quit").onclick=()=>{clearInterval(timer);show("start")};
